#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DTypeKind {
    Bool,
    SignedInteger,
    UnsignedInteger,
    Integral,
    RealFloating,
    ComplexFloating,
    Numeric,
}

pub fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    use DTypeKind::*;
    use NumpyDType::*;

    match kind {
        Bool => matches!(dtype, Bool),

        SignedInteger => matches!(dtype, Int8 | Int16 | Int32 | Int64),

        UnsignedInteger => matches!(dtype, UInt8 | UInt16 | UInt32 | UInt64),

        Integral => numpy_isdtype(dtype, SignedInteger) || numpy_isdtype(dtype, UnsignedInteger),

        RealFloating => matches!(dtype, Float16 | Float32 | Float64),

        ComplexFloating => matches!(dtype, Complex64 | Complex128),

        Numeric => {
            numpy_isdtype(dtype, Bool)
                || numpy_isdtype(dtype, SignedInteger)
                || numpy_isdtype(dtype, UnsignedInteger)
                || numpy_isdtype(dtype, RealFloating)
                || numpy_isdtype(dtype, ComplexFloating)
        }
    }
}

